const { request } = require('@dotenvx/tooling')
const buildApiError = require('./buildApiError')
const isNetworkError = require('./isNetworkError')

module.exports = async function armorRequest (endpoint, options, body) {
  // Bound each request, including its body; approval polling has its own deadline.
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 30000)
  timer.unref()
  try {
    const response = await request(`${options.hostname || 'https://armor.dotenvx.com'}/api/armor/${endpoint}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${options.token || ''}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ device_public_key: options.devicePublicKey, cli_version: options.cliVersion, ...body }),
      signal: controller.signal
    })
    const json = await response.body.json()
    if (response.statusCode >= 400) throw buildApiError(response.statusCode, json)
    return json
  } catch (error) {
    if (controller.signal.aborted || isNetworkError(error)) {
      const message = controller.signal.aborted ? 'Armor request timed out after 30 seconds' : 'unable to reach Armor'
      const help = 'check your connection or use --no-armor'
      throw Object.assign(new Error(`[ARMOR_UNREACHABLE] ${message}`), {
        code: 'ARMOR_UNREACHABLE',
        help,
        messageWithHelp: `[ARMOR_UNREACHABLE] ${message}. fix: [${help}]`,
        cause: error
      })
    }
    throw error
  } finally {
    clearTimeout(timer)
  }
}
